  "summary": "富有的四肢瘫痪贵族菲利普雇佣了来自塞纳河畔贫民区的黑人青年德里斯作为护工。两人出身、性格天差地别，却在朝夕相处中建立起超越阶级的真挚友谊。德里斯用粗犷的生命力唤醒了菲利普对生活的热情，菲利普则以包容与尊重改变了德里斯的人生轨迹。影片改编自真实事件，以轻盈幽默的笔触化解了残疾与阶层的沉重议题，证明了人与人之间真诚的连接可以跨越一切壁垒。",
  "review": "最好的友情不是同情而是平等相待，这部电影让你相信人与人之间最纯粹的善意。",
