  "summary": "印度少年派在海难后与一只孟加拉虎理查德·帕克同困救生艇，在太平洋上漂流227天。他以信仰、智慧与对老虎的敬畏维持生存，经历了食人岛、风暴与绝望。获救后他讲述了两个版本的故事，将选择权交给听众。李安以革命性的3D技术与极致的视觉美学，将扬·马特尔的小说转化为关于信仰、叙事与生存本质的银幕冥想。影片的美不仅是技术成就，更是通向哲学追问的路径。",
