  "summary": "川尻松子一生不断追逐爱与归属却屡屡被男人背叛、被家人抛弃、被社会吞噬，最终孤独死于破旧公寓。中岛哲也以绚烂至极的视觉风格和歌舞段落包装这个悲惨故事，形成强烈的美学反差——越是华丽的画面越衬托出命运的残酷。松子的'生而为人我很抱歉'成为对父权社会吞噬女性的沉痛控诉，华丽糖衣下是最苦涩的命运悲剧。视觉语言大胆华丽形式与内容形成巨大张力，松子形象令人心碎又愤怒。过度风格化可能遮蔽叙事本身，但这正是中岛哲也的美学宣言：用最美的方式讲最痛的故事，是日本电影美学的极端实验与女性悲剧的银幕丰碑。",
  "review": "用最美的方式讲最痛的故事，是日本电影美学的极端实验。",
  "pros": [
   "视觉语言大胆华丽，形式与内容形成张力",
   "松子形象令人心碎又愤怒"
  ],
  "cons": [
   "过度风格化可能遮蔽叙事本身"
  ],
