  "summary": "失业大提琴手小林大悟误打误撞成为入殓师，在为逝者整理仪容的过程中逐渐理解死亡的意义与生者应有的尊严。泷田洋二郎以庄重而不避讳的镜头呈现殡葬仪式的每一个细节，将社会禁忌转化为对生命终章的温柔注视与深切敬意。本木雅弘的表演内敛深沉每一个动作都经过精心打磨，影片获奥斯卡最佳外语片让全球观众重新思考'送别'的重量。对死亡的态度庄严而不沉重，久石让配乐与仪式场面完美融合。部分情节略显理想化，但它教会了我们如何体面地说再见，是一部跨越文化隔阂的生命教育课。",
