  "summary": "东欧旅客Viktor Navorski因祖国政变护照失效被困纽约肯尼迪机场航站楼长达数月无法入境也无法遣返。他以乐观善良与手工天赋赢得机场员工友谊，并在等待中追寻父亲收集爵士乐签名照的未竟心愿。斯皮尔伯格以Tom Hanks温润举重若轻的表演化解了身份困境的沉重，将机场这个过渡空间变成了关于归属、等待与人性温暖的寓言。机场生态描绘生动有趣各色人物鲜活，现实原型故事远比电影复杂美化过度，但这恰恰是斯皮尔伯格的温柔选择。这是他最被低估的温情小品，简单却拥有抚慰人心的持久力量。",
